insert into PBC_INIT_PROD_RAISING_SUB_HIS () select REGIST_SEQNO, PBC_PROD_ID, BUY_PLACE, CUSTOMER_TYPE1, CCY, INIT_RAISING_AMTSUM, INIT_RAISING_AMTSUMCNY, INIT_RAISING_QTY, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from PBC_INIT_PROD_RAISING_SUB where PBC_PROD_ID in
#{item.pbcProdId,jdbcType=CHAR}
and SEND_STATUS in ('02','03')

insert into PBC_INIT_PROD_RAISING_SUB () select HIS_NO, PBC_PROD_ID, BUY_PLACE, CUSTOMER_TYPE1, CCY, INIT_RAISING_AMTSUM, INIT_RAISING_AMTSUMCNY, INIT_RAISING_QTY, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from ( select , rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_INIT_PROD_RAISING_SUB_HIS where PBC_PROD_ID in
#{item.pbcProdId,jdbcType=CHAR}
order by PBC_PROD_ID, ifnull(update_time,create_time) desc ) tmp where ranknum = 1

mapper.delete:
delete from PBC_INIT_PROD_RAISING_SUB_HIS
where PBC_PROD_ID in (
select  PBC_PROD_ID
from (
select PBC_PROD_ID ,
rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum
from PBC_INIT_PROD_RAISING_SUB_HIS
where
PBC_PROD_ID in

  #{item.pbcProdId,jdbcType=CHAR}

) as T
where ranknum = 1
)

